import AppKit
import ImageIO
import MouseyClip
import Network

/// What may leave this Mac's clipboard, and how a received item is written. Takes the pasteboard as a value, so the
/// self-test never touches the person's real clipboard.
enum Clipboard {
	/// Marked by password managers and clipboard tools, per nspasteboard.org. Never sent.
	static let privateTypes: [NSPasteboard.PasteboardType] = [
		"org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
		"com.agilebits.onepassword", "com.dashlane.dashlanephonefinal", "net.antelle.keeweb",
		"de.petermaurer.TransientPasteboardType", "com.typeit4me.clipping", "Pasteboard generator type",
	].map { NSPasteboard.PasteboardType($0) }

	/// Another app can take as long as it likes to provide its data, so this runs off the main thread. Types and data are
	/// separate reads, so a change between them means the check no longer describes what was read.
	static func read(_ board: NSPasteboard) -> ClipItem? {
		let change = board.changeCount
		guard let types = board.types, !types.contains(where: privateTypes.contains), !types.contains(.fileURL) else { return nil }
		var item: ClipItem?
		// A copied image often carries a link to itself, and the image is what the person meant. Words beat both.
		if types.contains(.string), let text = board.string(forType: .string) {
			item = ClipItem(kind: .text, data: Data(text.utf8))
		} else if types.contains(.png), let data = board.data(forType: .png) {
			item = ClipItem(kind: .png, data: data)
		} else if types.contains(.tiff), let data = board.data(forType: .tiff) {
			item = convert(tiff: data)
		} else if types.contains(.URL), let url = board.string(forType: .URL) {
			item = ClipItem(kind: .url, data: Data(url.utf8))
		}
		return board.changeCount == change ? item : nil
	}

	/// A compressed TIFF can unpack to gigabytes, so its size is read from the header first.
	private static let maxPixels = 40_000_000

	static func convert(tiff: Data) -> ClipItem? {
		guard let source = CGImageSourceCreateWithData(tiff as CFData, nil),
			let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any],
			let width = properties[kCGImagePropertyPixelWidth] as? Int, let height = properties[kCGImagePropertyPixelHeight] as? Int,
			width > 0, height > 0, width <= maxPixels / height else { return nil }
		return NSBitmapImageRep(data: tiff)?.representation(using: .png, properties: [:]).flatMap { ClipItem(kind: .png, data: $0) }
	}

	/// Returns the board's change count after writing. This app never decodes a received image. Any app that asks the
	/// clipboard for it does, which can include clipboard managers.
	static func write(_ item: ClipItem, to board: NSPasteboard) -> Int {
		board.clearContents()
		switch item.kind {
		case .text:
			board.setString(String(decoding: item.data, as: UTF8.self), forType: .string)
		case .url:
			let url = String(decoding: item.data, as: UTF8.self)
			board.setString(url, forType: .URL)
			board.setString(url, forType: .string)
		case .png:
			board.setData(item.data, forType: .png)
		}
		return board.changeCount
	}
}

/// One end of the encrypted connection that carries clipboard content, on the main queue.
final class ClipChannel {
	private let connection: NWConnection
	private var buffer = Data()
	private let onItem: (ClipItem, ClipChannel) -> Void
	private let onState: (ClipChannel, Bool) -> Void
	private(set) var isReady = false
	private var closed = false

	init(_ connection: NWConnection, onItem: @escaping (ClipItem, ClipChannel) -> Void, onState: @escaping (ClipChannel, Bool) -> Void) {
		self.connection = connection
		self.onItem = onItem
		self.onState = onState
		connection.stateUpdateHandler = { [weak self] state in
			guard let self else { return }
			switch state {
			case .ready:
				guard SecureLink.isForwardSecret(connection) else { return close() }
				isReady = true
				onState(self, true)
				read()
			// Waiting covers a refused or unreachable peer and a wrong key. The keyboard Mac starts over instead.
			case .failed, .cancelled, .waiting:
				close()
			default:
				break
			}
		}
		connection.start(queue: .main)
	}

	func send(_ item: ClipItem) { connection.send(content: ClipFrame.encode(item), completion: .contentProcessed { _ in }) }

	func close() {
		guard !closed else { return }
		closed = true
		let wasReady = isReady
		isReady = false
		connection.stateUpdateHandler = nil
		// A handshake that never finished has nothing worth a clean goodbye, and a flood of them must free their files now.
		if wasReady { connection.cancel() } else { connection.forceCancel() }
		onState(self, false)
	}

	private func read() {
		connection.receive(minimumIncompleteLength: 1, maximumLength: 256 * 1024) { [weak self] data, _, isComplete, error in
			guard let self, !closed else { return }
			if let data { buffer.append(data) }
			while true {
				switch ClipFrame.next(&buffer) {
				case .needMore:
					if isComplete || error != nil { return close() }
					return read()
				case .item(let item):
					onItem(item, self)
					if closed { return }
				case .invalid:
					return close()
				}
			}
		}
	}
}

/// Moves clipboard content as input crosses. Each Mac runs one while sharing is on. Main thread.
final class ClipboardSync {
	enum Peer {
		/// The keyboard Mac starts the connection, as it does for input.
		case connect(peerID: String, address: String?)
		case listen(serviceName: String)
		/// Self-test: a loopback port, 0 meaning listen on any free one.
		case loopbackConnect(port: UInt16)
		case loopbackListen(port: UInt16?)
	}

	static let port: NWEndpoint.Port = 47802
	static let serviceType = "_mousey-clip._tcp"
	private static let maxPending = 8
	private static let maxHeldBack = 3

	/// The one the engines report crossings to.
	static var current: ClipboardSync?
	static func noteLeaving() { DispatchQueue.main.async { current?.leaving() } }
	static func noteArriving() { DispatchQueue.main.async { current?.arriving() } }

	private let key: Data
	private let peer: Peer
	private let board: NSPasteboard
	private let onConnected: (Bool) -> Void
	private var session: ClipSession
	private var listener: NWListener?
	private var channel: ClipChannel?
	private var pending: [ClipChannel] = []
	private var retry: Timer?
	private var tries = 0
	private var stopped = false
	private let reads = DispatchQueue(label: "mousey-clipboard-read", qos: .userInitiated)
	/// Moves on at every crossing, so a read that finishes late cannot be sent after input has moved again.
	private var crossing = 0
	private var heldBack = 0

	init(linkKey: Data, peer: Peer, board: NSPasteboard = .general, onConnected: @escaping (Bool) -> Void = { _ in }) {
		key = clipboardKey(fromLinkKey: linkKey)
		self.peer = peer
		self.board = board
		self.onConnected = onConnected
		session = ClipSession(changeCount: board.changeCount)
		switch peer {
		case .listen, .loopbackListen: listen()
		case .connect, .loopbackConnect:
			connect()
			let timer = Timer(timeInterval: 5, repeats: true) { [weak self] _ in
				if self?.channel == nil { self?.connect() }
			}
			RunLoop.main.add(timer, forMode: .common)
			retry = timer
		}
	}

	func stop() {
		stopped = true
		retry?.invalidate()
		listener?.cancel()
		channel?.close()
		pending.forEach { $0.close() }
		pending = []
	}

	var localPort: UInt16? { listener?.port?.rawValue }

	func leaving() {
		crossing &+= 1
		// A copy made while disconnected is still new at the next crossing.
		guard let channel, channel.isReady else { return }
		guard session.leaving(changeCount: board.changeCount) else { return }
		let thisCrossing = crossing
		let board = board
		reads.async {
			let item = Clipboard.read(board)
			DispatchQueue.main.async { [weak self, weak channel] in
				guard let self, !stopped, thisCrossing == crossing, let item, let channel, channel.isReady else { return }
				channel.send(item)
				Log.write("clipboard sent, \(item.data.count) bytes")
			}
		}
	}

	func arriving() {
		crossing &+= 1
		heldBack = 0
		if let item = session.arriving(now: ProcessInfo.processInfo.systemUptime, changeCount: board.changeCount) { apply(item) }
	}

	private func received(_ item: ClipItem, from sender: ClipChannel?) {
		if let item = session.receive(item, now: ProcessInfo.processInfo.systemUptime, changeCount: board.changeCount) {
			heldBack = 0
			return apply(item)
		}
		heldBack += 1
		// An honest Mac sends one item per crossing, so one line says enough, and a peer sending more loses the connection.
		if heldBack == 1 { Log.write("clipboard item outside a crossing was held back") }
		if heldBack > Self.maxHeldBack { sender?.close() }
	}

	private func apply(_ item: ClipItem) {
		session.applied(changeCount: Clipboard.write(item, to: board))
		Log.write("clipboard received, \(item.data.count) bytes")
	}

	/// The system's TLS with a key only the two paired Macs hold, and forward secrecy from the same suite as the input link.
	private func parameters(loopback: Bool) -> NWParameters {
		let tls = NWProtocolTLS.Options()
		func dispatchData(_ d: Data) -> __DispatchData { d.withUnsafeBytes { DispatchData(bytes: $0) } as __DispatchData }
		sec_protocol_options_add_pre_shared_key(tls.securityProtocolOptions, dispatchData(key), dispatchData(Data("mousey-clipboard".utf8)))
		sec_protocol_options_append_tls_ciphersuite(tls.securityProtocolOptions, tls_ciphersuite_t(rawValue: SecureLink.linkCipherSuite)!)
		sec_protocol_options_set_max_tls_protocol_version(tls.securityProtocolOptions, .TLSv12)
		let tcp = NWProtocolTCP.Options()
		tcp.noDelay = true
		tcp.enableKeepalive = true
		tcp.keepaliveIdle = 15
		tcp.keepaliveInterval = 5
		tcp.keepaliveCount = 3
		tcp.connectionTimeout = 5
		let result = NWParameters(tls: tls, tcp: tcp)
		if loopback { result.requiredInterfaceType = .loopback }
		return result
	}

	private func connect() {
		guard !stopped, channel == nil else { return }
		let endpoint: NWEndpoint
		var loopback = false
		switch peer {
		case .connect(let peerID, let address):
			if let address, tries % 2 == 0 {
				endpoint = .hostPort(host: NWEndpoint.Host(address.trimmingCharacters(in: .whitespaces)), port: Self.port)
			} else {
				endpoint = .service(name: peerID, type: Self.serviceType, domain: "local.", interface: nil)
			}
		case .loopbackConnect(let port):
			endpoint = .hostPort(host: "127.0.0.1", port: NWEndpoint.Port(rawValue: port)!)
			loopback = true
		case .listen, .loopbackListen:
			return
		}
		tries &+= 1
		let made = makeChannel(NWConnection(to: endpoint, using: parameters(loopback: loopback))) { [weak self] made, ready in
			guard let self, self.channel === made else { return }
			if !ready { self.channel = nil }
			self.onConnected(ready)
		}
		channel = made
		// A name that never resolves, or a peer that never finishes the handshake, would otherwise hold this slot for good.
		DispatchQueue.main.asyncAfter(deadline: .now() + 5) { [weak made] in
			if let made, !made.isReady { made.close() }
		}
	}

	private func listen() {
		var loopback = false
		let p: NWParameters
		if case .loopbackListen(let port) = peer {
			loopback = true
			p = parameters(loopback: true)
			p.requiredLocalEndpoint = .hostPort(host: "127.0.0.1", port: port.flatMap(NWEndpoint.Port.init(rawValue:)) ?? .any)
		} else {
			p = parameters(loopback: false)
		}
		guard let made = try? (loopback ? NWListener(using: p) : NWListener(using: p, on: Self.port)) else {
			Log.write("clipboard could not open its port")
			return listenAgainSoon()
		}
		if case .listen(let name) = peer { made.service = NWListener.Service(name: name, type: Self.serviceType) }
		made.newConnectionHandler = { [weak self] connection in self?.accept(connection) }
		made.stateUpdateHandler = { [weak self] state in
			guard case .failed(let error) = state else { return }
			Log.write("clipboard listener failed: \(error)")
			self?.listener?.cancel()
			self?.listener = nil
			self?.listenAgainSoon()
		}
		made.start(queue: .main)
		listener = made
	}

	private func listenAgainSoon() {
		DispatchQueue.main.asyncAfter(deadline: .now() + 3) { [weak self] in
			if self?.stopped == false, self?.listener == nil { self?.listen() }
		}
	}

	/// Anyone can start a handshake and only the paired Mac can finish one. The newest to finish is the peer, because a restarted Mac arrives on a new connection.
	private func accept(_ connection: NWConnection) {
		guard !stopped else { return connection.cancel() }
		if pending.count >= Self.maxPending { pending.removeFirst().close() }
		let made = makeChannel(connection) { [weak self] made, ready in
			guard let self else { return }
			self.pending.removeAll { $0 === made }
			if ready {
				self.channel?.close()
				self.channel = made
				self.onConnected(true)
			} else if self.channel === made {
				self.channel = nil
				self.onConnected(false)
			}
		}
		pending.append(made)
		DispatchQueue.main.asyncAfter(deadline: .now() + 5) { [weak self, weak made] in
			guard let self, let made, !made.isReady else { return }
			made.close()
			self.pending.removeAll { $0 === made }
		}
	}

	private func makeChannel(_ connection: NWConnection, onState: @escaping (ClipChannel, Bool) -> Void) -> ClipChannel {
		ClipChannel(connection, onItem: { [weak self] item, sender in self?.received(item, from: sender) }, onState: onState)
	}
}
